"""What reviewers said on a plan's pull request.

A task could be sent back with notes written in the app;
what a reviewer wrote on GitHub went nowhere. This reads it
-- inline comments on the diff, the text of reviews, and the
conversation -- so a human can pick what to act on and send
it through the same revision as any other note.

Read-only: nothing here writes to GitHub.
"""

from dataclasses import dataclass

from services.github_service import GitHubService

# DevLoop's own words, which are not feedback.
OWN_MARKERS = (
    "Generated by DevLoop",
    "**DevLoop** ran this task",
    "Split by DevLoop into:",
)


@dataclass
class ReviewComment:
    """One thing a reviewer said, wherever they said it."""

    # Stable across reads: "inline:<id>", "review:<id>" or
    # "comment:<id>", so an acted-on comment is recognised.
    key: str

    kind: str

    author: str = ""

    body: str = ""

    # For an inline comment: the file and line it is on.
    path: str = ""

    line: int = 0

    url: str = ""

    created_at: str = ""

    @property
    def where(self) -> str:

        if not self.path:
            return ""

        return f"{self.path}:{self.line}" if self.line else self.path

    def as_note(self) -> str:
        """The comment as a revision note: where, who, what."""

        place = f" on {self.where}" if self.where else ""

        text = " ".join(self.body.split())

        return f"PR review comment{place} by {self.author or 'a reviewer'}: {text}"


def is_feedback(body: str) -> bool:

    text = (body or "").strip()

    return bool(text) and not any(marker in text for marker in OWN_MARKERS)


def read(service: GitHubService, number: int) -> list[ReviewComment]:
    """Every reviewer comment on the request, oldest first.

    Reviews without text -- a bare approval -- and DevLoop's
    own comments are left out: there is nothing to act on.
    """

    found: list[ReviewComment] = []

    for item in service.list_review_comments(number):

        if not is_feedback(item.get("body")):
            continue

        found.append(
            ReviewComment(
                key=f"inline:{item.get('id')}",
                kind="inline",
                author=(item.get("user") or {}).get("login", ""),
                body=item.get("body") or "",
                path=item.get("path") or "",
                line=int(item.get("line") or item.get("original_line") or 0),
                url=item.get("html_url") or "",
                created_at=item.get("created_at") or "",
            )
        )

    for item in service.list_reviews(number):

        if not is_feedback(item.get("body")):
            continue

        found.append(
            ReviewComment(
                key=f"review:{item.get('id')}",
                kind="review",
                author=(item.get("user") or {}).get("login", ""),
                body=item.get("body") or "",
                url=item.get("html_url") or "",
                created_at=item.get("submitted_at") or "",
            )
        )

    for item in service.list_conversation(number):

        if not is_feedback(item.get("body")):
            continue

        found.append(
            ReviewComment(
                key=f"comment:{item.get('id')}",
                kind="comment",
                author=(item.get("user") or {}).get("login", ""),
                body=item.get("body") or "",
                url=item.get("html_url") or "",
                created_at=item.get("created_at") or "",
            )
        )

    return sorted(found, key=lambda comment: comment.created_at)


def owner_of(comment: ReviewComment, records) -> str:
    """The task record a comment is most likely about, or "".

    An inline comment names a file, and the latest record
    that wrote that file is its task. A general comment
    names none: the human chooses.
    """

    if not comment.path:
        return ""

    writers = [
        record
        for record in records
        if any(item.path == comment.path for item in record.generated_files)
    ]

    if not writers:
        return ""

    return max(writers, key=lambda record: record.created_at).id


def notes(comments: list[ReviewComment]) -> str:
    """Several comments as one revision's notes, one per line."""

    return "\n".join(comment.as_note() for comment in comments)
